int32_t to_pieces(Packing packing, int32_t packs) {
    return ccm::java::mul(packs, constant(packing).pieces);
}

Packing by_symbol(const std::string& symbol) {
    for (const Constant& c : kConstants) {
        if (symbol == c.symbol) {
            return c.packing;
        }
    }
    throw ccm::IllegalArgumentException("no packing " + symbol);
