namespace java = ccm::java;

namespace {

std::vector<char16_t> utf16(const std::string& text) {
    std::vector<char16_t> units;
    java::for_each_utf16(text, [&](char16_t unit) { units.push_back(unit); });
    return units;
}

// Character.isUpperCase(char) for Basic Latin and Latin-1: A-Z, and U+00C0-U+00DE but for the
// multiplication sign U+00D7. Java's tables also say yes for other scripts' capitals (Greek,
// Cyrillic, Latin Extended), which this port doesn't take as a family.
bool is_upper_case(char16_t unit) {
    if (unit >= u'A' && unit <= u'Z') {
        return true;
    }
    return unit >= 0xC0 && unit <= 0xDE && unit != 0xD7;
}

// String.trim: what is at most U+0020 at either end.
std::string trim(const std::string& text) {
    std::size_t begin = 0;
    std::size_t end = text.size();
    while (begin < end && static_cast<unsigned char>(text[begin]) <= 0x20) {
        ++begin;
    }
    while (end > begin && static_cast<unsigned char>(text[end - 1]) <= 0x20) {
        --end;
    }
    return text.substr(begin, end - begin);
}

// String.split("-"): the input whole when nothing matches, trailing empty strings dropped.
std::vector<std::string> split_on_dash(const std::string& text) {
    std::vector<std::string> parts;
    std::size_t start = 0;
    for (std::size_t i = 0; i <= text.size(); ++i) {
        if (i == text.size() || text[i] == '-') {
            parts.push_back(text.substr(start, i - start));
            start = i + 1;
        }
    }
    if (parts.size() == 1) {
        return parts;
    }
    while (!parts.empty() && parts.back().empty()) {
        parts.pop_back();
    }
    return parts;
}

// Integer.parseInt(s), its accepted forms (a sign, then ASCII digits) and its message.
int32_t parse_int(const std::string& s) {
    auto fail = [&]() { return ccm::NumberFormatException("For input string: \"" + s + "\""); };
    if (s.empty()) {
        throw fail();
    }
    std::size_t i = 0;
    bool negative = false;
    if (s[0] == '-' || s[0] == '+') {
        negative = s[0] == '-';
        i = 1;
        if (s.size() == 1) {
            throw fail();
        }
    }
    // Accumulate negatively, as Integer.parseInt does, so MIN_VALUE parses.
    const int64_t limit = negative ? INT32_MIN : -static_cast<int64_t>(INT32_MAX);
    int64_t result = 0;
    for (; i < s.size(); ++i) {
        const char c = s[i];
        if (c < '0' || c > '9') {
            throw fail();
        }
        result = result * 10 - (c - '0');
        if (result < limit) {
            throw fail();
        }
    }
    return static_cast<int32_t>(negative ? result : -result);
}

}  // namespace

Sku::Sku(std::string family, int32_t number) : family_(std::move(family)), number_(number) {
    const std::vector<char16_t> units = utf16(family_);
    if (units.size() != 2 || !is_upper_case(units[0]) || !is_upper_case(units[1])) {
        throw ccm::IllegalArgumentException("a family is two capital letters: " + family_);
    }
    if (number_ < 0 || number_ > 9999) {
        throw ccm::IllegalArgumentException("a number has four digits at most: " +
                                            std::to_string(number_));
    }
}

Sku Sku::parse(const std::string& text) {
    const std::vector<std::string> parts = split_on_dash(trim(text));
    if (parts.size() != 3) {
        throw ccm::IllegalArgumentException("not a SKU: " + text);
    }
    const int32_t number = parse_int(parts[1]);
    Sku sku(parts[0], number);
    if (sku.check_digit() != parse_int(parts[2])) {
        throw ccm::IllegalArgumentException("wrong check digit: " + text);
    }
    return sku;
}

int32_t Sku::check_digit() const {
    const std::vector<char16_t> units = utf16(family_);
    int32_t sum = static_cast<int32_t>(units[0]) + static_cast<int32_t>(units[1]);
    for (int32_t n = number_; n > 0; n /= 10) {
        sum += n % 10;
    }
    return sum % 10;
}

int32_t Sku::compare_to(const Sku& other) const {
    const std::vector<char16_t> mine = utf16(family_);
    const std::vector<char16_t> theirs = utf16(other.family_);
    const std::size_t common = mine.size() < theirs.size() ? mine.size() : theirs.size();
    for (std::size_t k = 0; k < common; ++k) {
        if (mine[k] != theirs[k]) {
            return static_cast<int32_t>(mine[k]) - static_cast<int32_t>(theirs[k]);
        }
    }
    const auto by_family =
        static_cast<int32_t>(mine.size()) - static_cast<int32_t>(theirs.size());
    if (by_family != 0) {
        return by_family;
    }
    return number_ < other.number_ ? -1 : (number_ == other.number_ ? 0 : 1);
}

int32_t Sku::hash_code() const noexcept {
    return java::add(java::mul<int32_t>(31, java::string_hash(family_)), number_);
}

std::string Sku::to_string() const {
    std::string digits = std::to_string(number_);
    while (java::string_length(digits) < 4) {
        digits = "0" + digits;
    }
    return family_ + "-" + digits + "-" + std::to_string(check_digit());
