void Stock::add_listener(std::shared_ptr<StockListener> listener) {
    const std::lock_guard<std::recursive_mutex> lock(mutex_);
    listeners_.push_back(std::move(listener));
}

void Stock::receive(const std::optional<Sku>& sku, std::optional<Packing> packing,
                    int32_t packs) {
    if (packs <= 0) {
        throw ccm::IllegalArgumentException("receive at least one pack: " +
                                            std::to_string(packs));
    }
    if (!packing) {
        throw ccm::NullPointerException();
    }
    change(sku, to_pieces(*packing, packs));
}

void Stock::take(const std::optional<Sku>& sku, int32_t pieces) {
    int32_t have = 0;
    {
        const std::lock_guard<std::recursive_mutex> lock(mutex_);
        const int32_t* count = find(sku);
        if (count == nullptr) {
            throw ccm::NoSuchElementException("never stocked: " + shown(sku));
        }
        have = *count;
    }
    if (pieces > have) {
        throw ccm::IllegalStateException("only " + std::to_string(have) + " of " + shown(sku) +
                                         " in stock");
    }
    change(sku, java::neg(pieces));
}

int32_t Stock::count(const std::optional<Sku>& sku) const {
    const std::lock_guard<std::recursive_mutex> lock(mutex_);
    const int32_t* count = find(sku);
    return count == nullptr ? 0 : *count;
}

int32_t Stock::total(const SkuFilter& filter) const {
    const std::lock_guard<std::recursive_mutex> lock(mutex_);
    int32_t total = 0;
    // A filter may call back into the stock. Reading it is Java's to allow; a new SKU stocked
    // meanwhile is a ConcurrentModificationException at the next entry, as Java's iterator
    // throws, and isn't visited after the last one.
    const std::size_t size = counts_.size();
    for (std::size_t i = 0; i < size; ++i) {
        if (counts_.size() != size) {
            throw ccm::ConcurrentModificationException();
        }
        if (!filter) {
            throw ccm::NullPointerException();
        }
        const auto entry = counts_[i];
        if (filter(entry.first)) {
            total = java::add(total, entry.second);
        }
    }
    return total;
}

std::string Stock::report() const {
    const std::lock_guard<std::recursive_mutex> lock(mutex_);
    std::string out;
    for (const auto& [sku, count] : counts_) {
        out += shown(sku) + ": " + std::to_string(count) + "\n";
    }
