package org.example.warehouse;

import codecoremorph.interop.CcmInterop;
import codecoremorph.interop.CcmNative;

/**
 * Counts of the warehouse's SKUs, in the order they were first stocked, and the listeners told
 * of each change. Safe to share between threads.
 */
public class Stock {
    private final long handle;

    public Stock() {
        long[] result = new long[1];
        CcmInterop.check(CcmNative.warehouse_Stock_new(result));
        handle = CcmInterop.track(this, result[0], CcmNative::warehouse_Stock_release);
    }

    public synchronized void addListener(StockListener listener) {
        long listenerHandle = StockListeners.handleOf(listener);
        try {
            CcmInterop.check(CcmNative.warehouse_Stock_addListener(handle, listenerHandle));
        } finally {
            CcmNative.warehouse_StockListener_release(listenerHandle);
        }
    }

    /** Receives a number of packs of a SKU. */
    public void receive(Sku sku, Packing packing, int packs) {
        CcmInterop.check(CcmNative.warehouse_Stock_receive(handle, Sku.familyOf(sku),
            Sku.numberOf(sku), packing == null ? -1 : packing.ordinal(), packs));
    }

    /** Takes pieces out; NoSuchElementException for a SKU never stocked. */
    public void take(Sku sku, int pieces) {
        CcmInterop.check(CcmNative.warehouse_Stock_take(handle, Sku.familyOf(sku),
            Sku.numberOf(sku), pieces));
    }

    public synchronized int count(Sku sku) {
        int[] result = new int[1];
        CcmInterop.check(CcmNative.warehouse_Stock_count(handle, Sku.familyOf(sku),
            Sku.numberOf(sku), result));
        return result[0];
    }

    /** How many pieces of the SKUs the filter accepts are in stock. */
    public synchronized int total(final SkuFilter filter) {
        int[] result = new int[1];
        CcmInterop.check(CcmNative.warehouse_Stock_total(handle, filter == null ? null
            : new CcmNative.warehouse_Stock_SkuFilter_accepts_fn() {
                @Override
                public int call(String skuFamily, int skuNumber, boolean[] accepted) {
                    accepted[0] = filter.accepts(Sku.of(skuFamily, skuNumber));
                    return CcmInterop.OK;
                }
            }, result));
        return result[0];
    }

    /** One line per SKU, in the order they were first stocked: "AB-1234-7: 12". */
    public synchronized String report() {
        String[] result = new String[1];
        CcmInterop.check(CcmNative.warehouse_Stock_report(handle, result));
        return result[0];
    }

    /** Accepts or rejects a SKU. */
    public interface SkuFilter {
        boolean accepts(Sku sku);
    }
}

